///
/// ```no_run
/// use chainflow_data_gateway::transport::{MockTransport, SdkBody, Transport};
///
/// # async fn demo() {
/// let mock = MockTransport::new();
/// mock.enqueue(200, r#"{"id":"user_1"}"#);
///
/// // Normally the clone goes into the client builder; the mock itself is a
/// // `Transport`, so it can also be driven directly.
/// let transport = mock.clone();
/// let request = http::Request::post("https://api.example.com/users")
///     .body(SdkBody::from_bytes(r#"{"name":"Ada"}"#))
///     .expect("valid request");
/// let response = transport.execute(request).await.expect("a queued response");
/// assert_eq!(response.status(), 200);
///
/// let recorded = mock.requests();
/// assert_eq!(recorded.len(), 1);
/// assert_eq!(recorded[0].method, http::Method::POST);
/// assert_eq!(&recorded[0].body[..], &br#"{"name":"Ada"}"#[..]);
/// # }
/// ```
#[cfg(feature = "mock")]
#[derive(Debug, Clone, Default)]
pub struct MockTransport {
    /// Shared interior so clones observe one queue and one request log.
    state: Arc<std::sync::Mutex<MockState>>,
}

/// Interior state shared by every clone of a [`MockTransport`].
#[cfg(feature = "mock")]
#[derive(Debug, Default)]
struct MockState {
    /// Responses handed out in FIFO order.
    queue: std::collections::VecDeque<http::Response<SdkBody>>,
    /// Every executed request, in arrival order.
    requests: Vec<RecordedRequest>,
}

/// A request captured by [`MockTransport`], with its body fully buffered so
/// tests can assert on the exact bytes sent.
#[cfg(feature = "mock")]
#[derive(Debug, Clone)]
pub struct RecordedRequest {
    /// The request method.
    pub method: http::Method,
    /// The full request URI.
    pub uri: http::Uri,
    /// The request headers.
    pub headers: http::HeaderMap,
    /// The collected request body.
    pub body: Bytes,
}

#[cfg(feature = "mock")]
impl MockTransport {
    /// Creates a mock transport with an empty response queue.
    pub fn new() -> Self {
        Self::default()
    }

    /// Enqueues a `status` response with `body` and a
    /// `content-type: application/json` header, returning `&self` for
    /// chaining.
    ///
    /// # Panics
    ///
    /// Panics when `status` is not a valid HTTP status code — a mock
    /// configured with an impossible response is a test bug (test-only
    /// carve-out).
    pub fn enqueue(&self, status: u16, body: impl Into<Bytes>) -> &Self {
        let response = http::Response::builder()
            .status(status)
            .header(http::header::CONTENT_TYPE, "application/json")
            .body(SdkBody::from_bytes(body.into()))
            .unwrap_or_else(|error| panic!("MockTransport::enqueue: invalid response (status {status}): {error}"));
        self.state().queue.push_back(response);
        self
    }

    /// Enqueues a pre-built response, for cases [`MockTransport::enqueue`]
    /// does not cover (custom headers, streaming bodies), returning `&self`
    /// for chaining.
    pub fn enqueue_response(&self, response: http::Response<SdkBody>) -> &Self {
        self.state().queue.push_back(response);
        self
    }

    /// All requests executed so far, in order, with bodies buffered.
    pub fn requests(&self) -> Vec<RecordedRequest> {
        self.state().requests.clone()
    }

    /// Locks the shared state, recovering from a poisoned lock so one failed
    /// test thread does not cascade panics into unrelated assertions.
    fn state(&self) -> std::sync::MutexGuard<'_, MockState> {
        self.state.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
    }
}

#[cfg(feature = "mock")]
impl Transport for MockTransport {
    fn execute(
        &self,
        request: http::Request<SdkBody>,
    ) -> BoxFuture<'_, Result<http::Response<SdkBody>, TransportError>> {
        let state = Arc::clone(&self.state);
        Box::pin(async move {
            let (parts, body) = request.into_parts();
            // Collect before locking: buffering the body is async and must not
            // hold the mutex across an await point.
            let body = body.collect().await?;
            let mut state = state.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            state.requests.push(RecordedRequest {
                method: parts.method,
                uri: parts.uri,
                headers: parts.headers,
                body,
            });
            match state.queue.pop_front() {
                Some(response) => Ok(response),
                // Test-only carve-out: an unexpected extra request in a test
                // should fail loudly, not limp along with a synthetic error.
                None => panic!(
                    "MockTransport response queue is exhausted: enqueue a response for every request the test issues"
                ),
            }
        })
    }
}

